for x in select value from jsonb_array_elements('[{"identity":"repo:https://github.com/agricidaniel/claude-seo","slug":"claude-seo-0e986095","name":"Claude SEO","type":"SKILL","status":"CANDIDATE","tagline":"Audit SEO cần danh sách việc sửa có căn cứ, không chỉ một điểm số đẹp.","description":"Claude SEO là plugin phân tích SEO cho Claude Code, chia việc kiểm tra thành các skill và vai trò chuyên biệt. Phạm vi gồm chất lượng nội dung, SEO kỹ thuật, schema, AI search, local và thương mại điện tử. Giá trị với người viết là nhận biết phần nào trong bài và website cần cải thiện, rồi đối chiếu lại khuyến nghị trước khi triển khai.","long_description":"ĐIỂM NỔI BẬT\n• Kiểm tra nội dung và khả năng được máy tìm kiếm/AI đọc hiểu cùng những vấn đề kỹ thuật liên quan.\n• Tạo kế hoạch ưu tiên hành động, có quan sát và cách kiểm tra kết quả.\n• Phân biệt bản công khai MIT với bản mirror cộng đồng có điều kiện truy cập riêng.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nAudit một trang review tool để tìm chỗ thiếu thông tin gốc, cấu trúc nội dung hoặc dữ liệu đánh dấu; chọn các sửa đổi có thể kiểm chứng.\n\nBẮT ĐẦU\nCài plugin công khai theo README và chạy thiết lập môi trường đi kèm. Cần Claude Code, Python/trình duyệt theo yêu cầu công cụ.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nTrang dựng nặng bằng JavaScript có thể gây kết quả nhiễu. Audit local không thay thế dữ liệu Search Console, và gợi ý SEO/GEO không bảo đảm thứ hạng hoặc được AI trích dẫn.","canonical_url":"https://github.com/AgriciDaniel/claude-seo","repository_url":"https://github.com/AgriciDaniel/claude-seo","documentation_url":"https://raw.githubusercontent.com/AgriciDaniel/claude-seo/main/README.md","owner_name":"AgriciDaniel","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":11,"categories":["seo","content"],"primaryCategory":"seo","selectionReason":"Phù hợp SEO & Analytics: Audit SEO cần danh sách việc sửa có căn cứ, không chỉ một điểm số đẹp. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Audit SEO cần danh sách việc sửa có căn cứ, không chỉ một điểm số đẹp.","highlights":["Kiểm tra nội dung và khả năng được máy tìm kiếm/AI đọc hiểu cùng những vấn đề kỹ thuật liên quan.","Tạo kế hoạch ưu tiên hành động, có quan sát và cách kiểm tra kết quả.","Phân biệt bản công khai MIT với bản mirror cộng đồng có điều kiện truy cập riêng."],"example":"Audit một trang review tool để tìm chỗ thiếu thông tin gốc, cấu trúc nội dung hoặc dữ liệu đánh dấu; chọn các sửa đổi có thể kiểm chứng.","setup":"Cài plugin công khai theo README và chạy thiết lập môi trường đi kèm. Cần Claude Code, Python/trình duyệt theo yêu cầu công cụ.","limitations":"Trang dựng nặng bằng JavaScript có thể gây kết quả nhiễu. Audit local không thay thế dữ liệu Search Console, và gợi ý SEO/GEO không bảo đảm thứ hạng hoặc được AI trích dẫn.","github":{"stars":16211,"forks":2369,"observedAt":"2026-09-03T16:08:02.616Z","url":"https://github.com/AgriciDaniel/claude-seo","pushedAt":"2026-08-26T12:16:22Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/AgriciDaniel/claude-seo/main/README.md","observedAt":"2026-09-03T16:09:41.182Z","sha256":"1d35315c7c0af7bdefcd3d89d568f1f0df1eebe8fdc6bd095c54c574865a5afb"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"AgriciDaniel/claude-seo:metadata","source_url":"https://github.com/AgriciDaniel/claude-seo","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Amendableai%2Ffirecrawl%20repo%3Aunclecode%2Fcrawl4ai%20repo%3Abrowser-use%2Fbrowser-use%20repo%3Ajina-ai%2Freader%20repo%3Amicrosoft%2Fmarkitdown%20repo%3Ahamidteimour%2Fseo-audit-skill%20repo%3AAgriciDaniel%2Fclaude-seo%20repo%3Aonur-genc%2Fseo-mcp&per_page=100","stars":16211,"forks":2369,"license":"MIT"},"fetched_at":"2026-09-03T16:08:02.616Z"},{"source_type":"github","source_identifier":"AgriciDaniel/claude-seo:readme:1d35315c7c0af7bdefcd3d89d568f1f0df1eebe8fdc6bd095c54c574865a5afb","source_url":"https://raw.githubusercontent.com/AgriciDaniel/claude-seo/main/README.md","raw_metadata":{"sha256":"1d35315c7c0af7bdefcd3d89d568f1f0df1eebe8fdc6bd095c54c574865a5afb","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:41.182Z"}],"expected":null},{"identity":"repo:https://github.com/presenton/presenton","slug":"presenton-e8677b30","name":"Presenton","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Từ tài liệu hoặc prompt tới deck có thể sửa tiếp, dùng model và template bạn chọn.","description":"Presenton là công cụ tạo presentation bằng AI, có desktop, self-host, giao diện chỉnh và xuất PowerPoint/PDF. Điểm hấp dẫn với creator là biến tài liệu dài thành bản nháp trình bày rồi chỉnh theo thương hiệu, không khóa vào một nhà cung cấp model duy nhất.","long_description":"ĐIỂM NỔI BẬT\n• Tạo từ prompt, tài liệu hoặc template PowerPoint.\n• Có giao diện chỉnh kéo thả và xuất PPTX được chính chủ mô tả là chỉnh sửa được.\n• Hỗ trợ model local/BYOK, API và MCP cho workflow.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nĐưa tài liệu đã kiểm chứng vào để tạo outline và deck hướng dẫn, sửa số liệu/nguồn rồi xuất bản cho học viên.\n\nBẮT ĐẦU\nChọn desktop hoặc Docker, cấu hình model và template; bắt đầu bằng tài liệu không nhạy cảm.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nSelf-host không đồng nghĩa toàn bộ dữ liệu luôn local nếu bật provider cloud hoặc nguồn ảnh ngoài. AI có thể sai số, nguồn và bố cục; phí API tính riêng.","canonical_url":"https://github.com/presenton/presenton","repository_url":"https://github.com/presenton/presenton","documentation_url":"https://raw.githubusercontent.com/presenton/presenton/main/README.md","owner_name":"presenton","license":"Apache-2.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":12,"categories":["design","content"],"primaryCategory":"design","selectionReason":"Phù hợp Design & Frontend: Từ tài liệu hoặc prompt tới deck có thể sửa tiếp, dùng model và template bạn chọn. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Từ tài liệu hoặc prompt tới deck có thể sửa tiếp, dùng model và template bạn chọn.","highlights":["Tạo từ prompt, tài liệu hoặc template PowerPoint.","Có giao diện chỉnh kéo thả và xuất PPTX được chính chủ mô tả là chỉnh sửa được.","Hỗ trợ model local/BYOK, API và MCP cho workflow."],"example":"Đưa tài liệu đã kiểm chứng vào để tạo outline và deck hướng dẫn, sửa số liệu/nguồn rồi xuất bản cho học viên.","setup":"Chọn desktop hoặc Docker, cấu hình model và template; bắt đầu bằng tài liệu không nhạy cảm.","limitations":"Self-host không đồng nghĩa toàn bộ dữ liệu luôn local nếu bật provider cloud hoặc nguồn ảnh ngoài. AI có thể sai số, nguồn và bố cục; phí API tính riêng.","github":{"stars":9995,"forks":1552,"observedAt":"2026-09-03T16:09:07.643Z","url":"https://github.com/presenton/presenton","pushedAt":"2026-09-03T06:47:57Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/presenton/presenton/main/README.md","observedAt":"2026-09-03T16:10:47.069Z","sha256":"53dcc783675836849e9e8b42d59aa8a71085bef07d717cb8a852a6b834f2a6ef"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"presenton/presenton:metadata","source_url":"https://github.com/presenton/presenton","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Apresenton%2Fpresenton%20repo%3Amarp-team%2Fmarp%20repo%3Anextlevelbuilder%2Fui-ux-pro-max-skill%20repo%3Apbakaus%2Fimpeccable%20repo%3Aleonxlnx%2Ftaste-skill%20repo%3Ashadcn-ui%2Fui%20repo%3An8n-io%2Fn8n%20repo%3Aactivepieces%2Factivepieces&per_page=100","stars":9995,"forks":1552,"license":"Apache-2.0"},"fetched_at":"2026-09-03T16:09:07.643Z"},{"source_type":"github","source_identifier":"presenton/presenton:readme:53dcc783675836849e9e8b42d59aa8a71085bef07d717cb8a852a6b834f2a6ef","source_url":"https://raw.githubusercontent.com/presenton/presenton/main/README.md","raw_metadata":{"sha256":"53dcc783675836849e9e8b42d59aa8a71085bef07d717cb8a852a6b834f2a6ef","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:47.069Z"}],"expected":null},{"identity":"repo:https://github.com/knadh/listmonk","slug":"listmonk-079b7fdd","name":"listmonk","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Xây danh sách độc giả của riêng bạn, không chỉ phụ thuộc vào lượt tiếp cận từ thuật toán.","description":"listmonk là phần mềm tự host để quản lý newsletter và mailing list. Ứng dụng được đóng gói gọn trong một tệp thực thi, dùng PostgreSQL để lưu dữ liệu và có giao diện web. Nó phù hợp khi bạn đã có nội dung và muốn vận hành kênh email riêng, thay vì tìm một AI viết bài thay mình.","long_description":"ĐIỂM NỔI BẬT\n• Quản lý newsletter và danh sách email trong hệ thống bạn tự vận hành.\n• Có bản Docker và bản thực thi độc lập, không buộc phải dựng cả môi trường phát triển.\n• Tác giả cung cấp demo trực tuyến để xem trước giao diện trước khi triển khai.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nTổng hợp các video hay trong tuần thành bản tin email, gửi cho người đăng ký nhận tin và giữ lại danh sách độc giả do bạn quản lý.\n\nBẮT ĐẦU\nThử demo chính chủ trước. Khi dùng thật, triển khai Docker hoặc binary, cấu hình PostgreSQL và dịch vụ gửi email theo tài liệu.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nĐây không phải dịch vụ chuyển phát email miễn phí sẵn có. Cần cấu hình gửi thư, quản lý đồng ý nhận tin, hủy đăng ký và uy tín tên miền; không nhập danh sách mua ngoài.","canonical_url":"https://github.com/knadh/listmonk","repository_url":"https://github.com/knadh/listmonk","documentation_url":"https://raw.githubusercontent.com/knadh/listmonk/master/README.md","owner_name":"knadh","license":"AGPL-3.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":13,"categories":["social","content"],"primaryCategory":"social","selectionReason":"Phù hợp Social & Marketing: Xây danh sách độc giả của riêng bạn, không chỉ phụ thuộc vào lượt tiếp cận từ thuật toán. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Xây danh sách độc giả của riêng bạn, không chỉ phụ thuộc vào lượt tiếp cận từ thuật toán.","highlights":["Quản lý newsletter và danh sách email trong hệ thống bạn tự vận hành.","Có bản Docker và bản thực thi độc lập, không buộc phải dựng cả môi trường phát triển.","Tác giả cung cấp demo trực tuyến để xem trước giao diện trước khi triển khai."],"example":"Tổng hợp các video hay trong tuần thành bản tin email, gửi cho người đăng ký nhận tin và giữ lại danh sách độc giả do bạn quản lý.","setup":"Thử demo chính chủ trước. Khi dùng thật, triển khai Docker hoặc binary, cấu hình PostgreSQL và dịch vụ gửi email theo tài liệu.","limitations":"Đây không phải dịch vụ chuyển phát email miễn phí sẵn có. Cần cấu hình gửi thư, quản lý đồng ý nhận tin, hủy đăng ký và uy tín tên miền; không nhập danh sách mua ngoài.","github":{"stars":23238,"forks":2578,"observedAt":"2026-09-03T16:07:36.757Z","url":"https://github.com/knadh/listmonk","pushedAt":"2026-09-03T05:01:00Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/knadh/listmonk/master/README.md","observedAt":"2026-09-03T16:09:15.102Z","sha256":"e3592dcea72705901f2cfba4f674de81e96dc7aaded2343246cca9312a092cee"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"knadh/listmonk:metadata","source_url":"https://github.com/knadh/listmonk","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Acharlie947%2Fsocial-media-skills%20repo%3Agitroomhq%2Fpostiz-app%20repo%3Ainovector%2Fmixpost%20repo%3Atrypostit%2Ftrypost%20repo%3Aleamsigc%2FMagicSync%20repo%3Amautic%2Fmautic%20repo%3Aknadh%2Flistmonk%20repo%3Auseplunk%2Fplunk&per_page=100","stars":23238,"forks":2578,"license":"AGPL-3.0"},"fetched_at":"2026-09-03T16:07:36.757Z"},{"source_type":"github","source_identifier":"knadh/listmonk:readme:e3592dcea72705901f2cfba4f674de81e96dc7aaded2343246cca9312a092cee","source_url":"https://raw.githubusercontent.com/knadh/listmonk/master/README.md","raw_metadata":{"sha256":"e3592dcea72705901f2cfba4f674de81e96dc7aaded2343246cca9312a092cee","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:15.102Z"}],"expected":null},{"identity":"repo:https://github.com/mautic/mautic","slug":"mautic-223915d3","name":"Mautic","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Biến chuỗi email rời rạc thành một hành trình chăm sóc người quan tâm.","description":"Mautic là nền tảng marketing automation mã nguồn mở, tập trung vào chiến dịch tích hợp, phân nhóm khách hàng và quyền kiểm soát dữ liệu. Công cụ phù hợp với đội content/marketing đã có nhiều điểm chạm cần phối hợp, hơn là người chỉ muốn đăng một bài social. Bạn tự quản lý hệ thống và có thể mở rộng theo cách vận hành của mình.","long_description":"ĐIỂM NỔI BẬT\n• Phân nhóm người liên hệ và thiết kế các bước tự động hóa marketing.\n• Hỗ trợ chiến dịch đa kênh cùng khả năng tùy biến và tích hợp.\n• Tự triển khai để kiểm soát dữ liệu, không khóa toàn bộ hoạt động trong một nhà cung cấp SaaS.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nNgười xem tải tài liệu hướng dẫn làm video; bạn phân nhóm theo nhu cầu rồi gửi chuỗi bài học phù hợp, thay vì gửi cùng một nội dung cho mọi người.\n\nBẮT ĐẦU\nDùng bản phát hành và hướng dẫn production chính chủ. README khuyên không đưa bản mã đang phát triển từ GitHub vào vận hành thực tế.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nCần vận hành máy chủ, cơ sở dữ liệu, email và cập nhật bảo mật. Không phải ứng dụng cài một chạm; phải có đồng ý nhận tin và quy trình bảo vệ dữ liệu người liên hệ.","canonical_url":"https://github.com/mautic/mautic","repository_url":"https://github.com/mautic/mautic","documentation_url":"https://raw.githubusercontent.com/mautic/mautic/7.x/README.md","owner_name":"mautic","license":"Chưa xác nhận giấy phép; cần đọc LICENSE chính chủ trước khi sử dụng.","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":14,"categories":["social","automation"],"primaryCategory":"social","selectionReason":"Phù hợp Social & Marketing: Biến chuỗi email rời rạc thành một hành trình chăm sóc người quan tâm. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Biến chuỗi email rời rạc thành một hành trình chăm sóc người quan tâm.","highlights":["Phân nhóm người liên hệ và thiết kế các bước tự động hóa marketing.","Hỗ trợ chiến dịch đa kênh cùng khả năng tùy biến và tích hợp.","Tự triển khai để kiểm soát dữ liệu, không khóa toàn bộ hoạt động trong một nhà cung cấp SaaS."],"example":"Người xem tải tài liệu hướng dẫn làm video; bạn phân nhóm theo nhu cầu rồi gửi chuỗi bài học phù hợp, thay vì gửi cùng một nội dung cho mọi người.","setup":"Dùng bản phát hành và hướng dẫn production chính chủ. README khuyên không đưa bản mã đang phát triển từ GitHub vào vận hành thực tế.","limitations":"Cần vận hành máy chủ, cơ sở dữ liệu, email và cập nhật bảo mật. Không phải ứng dụng cài một chạm; phải có đồng ý nhận tin và quy trình bảo vệ dữ liệu người liên hệ.","github":{"stars":10435,"forks":3435,"observedAt":"2026-09-03T16:07:36.757Z","url":"https://github.com/mautic/mautic","pushedAt":"2026-09-03T15:26:31Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/mautic/mautic/7.x/README.md","observedAt":"2026-09-03T16:09:16.016Z","sha256":"40c69df29d472584293e90818689009a2b01eca9e657e62a3a997d499d3c9ae3"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"mautic/mautic:metadata","source_url":"https://github.com/mautic/mautic","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Acharlie947%2Fsocial-media-skills%20repo%3Agitroomhq%2Fpostiz-app%20repo%3Ainovector%2Fmixpost%20repo%3Atrypostit%2Ftrypost%20repo%3Aleamsigc%2FMagicSync%20repo%3Amautic%2Fmautic%20repo%3Aknadh%2Flistmonk%20repo%3Auseplunk%2Fplunk&per_page=100","stars":10435,"forks":3435,"license":"NOASSERTION"},"fetched_at":"2026-09-03T16:07:36.757Z"},{"source_type":"github","source_identifier":"mautic/mautic:readme:40c69df29d472584293e90818689009a2b01eca9e657e62a3a997d499d3c9ae3","source_url":"https://raw.githubusercontent.com/mautic/mautic/7.x/README.md","raw_metadata":{"sha256":"40c69df29d472584293e90818689009a2b01eca9e657e62a3a997d499d3c9ae3","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:16.016Z"}],"expected":null},{"identity":"repo:https://github.com/useplunk/plunk","slug":"plunk-bd98c323","name":"Plunk","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Email giao dịch, chiến dịch và tự động hóa có thể nằm trong cùng một chỗ.","description":"Plunk là nền tảng email mã nguồn mở kết hợp quản lý người liên hệ, phân nhóm, chiến dịch và workflow. Điểm hữu ích cho người bán sản phẩm số hoặc làm newsletter là nối các email vận hành với hoạt động marketing, thay vì quản lý nhiều danh sách tách biệt. README cũng nêu analytics và hỗ trợ tên miền gửi riêng.","long_description":"ĐIỂM NỔI BẬT\n• Quản lý contact với trường thông tin tùy chỉnh và lịch sử hoạt động.\n• Tạo segment và workflow để gửi đúng nhóm, đúng tình huống.\n• Theo dõi mở thư, click, bounce và xác thực tên miền bằng DKIM/SPF.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nSau khi người xem đăng ký nhận một bộ template, gửi email bàn giao rồi đưa họ vào nhóm nhận mẹo sử dụng phù hợp.\n\nBẮT ĐẦU\nLàm theo hướng dẫn self-host chính chủ bằng Docker; cấu hình tên miền gửi và các dịch vụ email cần thiết trước khi gửi thật.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nOpen source không đồng nghĩa gửi email không tốn phí. Deliverability còn phụ thuộc hạ tầng, uy tín tên miền và chất lượng danh sách. Số lượt mở không phản ánh hoàn toàn số người thực sự đọc.","canonical_url":"https://github.com/useplunk/plunk","repository_url":"https://github.com/useplunk/plunk","documentation_url":"https://raw.githubusercontent.com/useplunk/plunk/next/README.md","owner_name":"useplunk","license":"AGPL-3.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":15,"categories":["social","automation"],"primaryCategory":"social","selectionReason":"Phù hợp Social & Marketing: Email giao dịch, chiến dịch và tự động hóa có thể nằm trong cùng một chỗ. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Email giao dịch, chiến dịch và tự động hóa có thể nằm trong cùng một chỗ.","highlights":["Quản lý contact với trường thông tin tùy chỉnh và lịch sử hoạt động.","Tạo segment và workflow để gửi đúng nhóm, đúng tình huống.","Theo dõi mở thư, click, bounce và xác thực tên miền bằng DKIM/SPF."],"example":"Sau khi người xem đăng ký nhận một bộ template, gửi email bàn giao rồi đưa họ vào nhóm nhận mẹo sử dụng phù hợp.","setup":"Làm theo hướng dẫn self-host chính chủ bằng Docker; cấu hình tên miền gửi và các dịch vụ email cần thiết trước khi gửi thật.","limitations":"Open source không đồng nghĩa gửi email không tốn phí. Deliverability còn phụ thuộc hạ tầng, uy tín tên miền và chất lượng danh sách. Số lượt mở không phản ánh hoàn toàn số người thực sự đọc.","github":{"stars":5422,"forks":397,"observedAt":"2026-09-03T16:07:36.757Z","url":"https://github.com/useplunk/plunk","pushedAt":"2026-09-03T12:16:44Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/useplunk/plunk/next/README.md","observedAt":"2026-09-03T16:09:16.959Z","sha256":"1ccbbbbaaf051155b365a84ac72dbeb4c775a190ec06aec63a96f2867279fab7"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"useplunk/plunk:metadata","source_url":"https://github.com/useplunk/plunk","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Acharlie947%2Fsocial-media-skills%20repo%3Agitroomhq%2Fpostiz-app%20repo%3Ainovector%2Fmixpost%20repo%3Atrypostit%2Ftrypost%20repo%3Aleamsigc%2FMagicSync%20repo%3Amautic%2Fmautic%20repo%3Aknadh%2Flistmonk%20repo%3Auseplunk%2Fplunk&per_page=100","stars":5422,"forks":397,"license":"AGPL-3.0"},"fetched_at":"2026-09-03T16:07:36.757Z"},{"source_type":"github","source_identifier":"useplunk/plunk:readme:1ccbbbbaaf051155b365a84ac72dbeb4c775a190ec06aec63a96f2867279fab7","source_url":"https://raw.githubusercontent.com/useplunk/plunk/next/README.md","raw_metadata":{"sha256":"1ccbbbbaaf051155b365a84ac72dbeb4c775a190ec06aec63a96f2867279fab7","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:16.959Z"}],"expected":null},{"identity":"repo:https://github.com/inovector/mixpost","slug":"mixpost-lite-6d99c5e6","name":"Mixpost Lite","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Gom lịch đăng và tài nguyên social về một bàn làm việc do bạn quản lý.","description":"Mixpost là hệ thống quản lý nội dung mạng xã hội, hướng tới thương hiệu, agency và người làm độc lập. Repo này là bản Lite của sản phẩm Mixpost, không phải toàn bộ tính năng Pro/Enterprise. Nó đáng xem khi bạn cần tổ chức công việc đăng bài, nội dung và tài khoản social một cách chủ động hơn.","long_description":"ĐIỂM NỔI BẬT\n• Quy trình soạn, tổ chức và lên lịch nội dung social.\n• Hệ sinh thái có quản lý media, lịch/queue và mẫu bài tái sử dụng.\n• README phân biệt rõ bản Lite nguồn mở với các phiên bản thương mại — cần đối chiếu tính năng trước khi chọn.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nLập lịch đăng cho một thương hiệu nhỏ và tái sử dụng kho hình/video giữa các bài, sau khi xác nhận bản Lite hỗ trợ các kênh bạn cần.\n\nBẮT ĐẦU\nBắt đầu từ tài liệu Mixpost Lite được dẫn trong README, không dùng bảng tính năng toàn bộ sản phẩm để suy đoán khả năng bản miễn phí.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nNhiều tính năng được giới thiệu cho hệ sinh thái Mixpost có thể thuộc Pro/Enterprise. Tích hợp social phụ thuộc API nền tảng; tự host cần cấu hình và bảo trì.","canonical_url":"https://github.com/inovector/mixpost","repository_url":"https://github.com/inovector/mixpost","documentation_url":"https://raw.githubusercontent.com/inovector/mixpost/main/README.md","owner_name":"inovector","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":16,"categories":["social","content"],"primaryCategory":"social","selectionReason":"Phù hợp Social & Marketing: Gom lịch đăng và tài nguyên social về một bàn làm việc do bạn quản lý. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Gom lịch đăng và tài nguyên social về một bàn làm việc do bạn quản lý.","highlights":["Quy trình soạn, tổ chức và lên lịch nội dung social.","Hệ sinh thái có quản lý media, lịch/queue và mẫu bài tái sử dụng.","README phân biệt rõ bản Lite nguồn mở với các phiên bản thương mại — cần đối chiếu tính năng trước khi chọn."],"example":"Lập lịch đăng cho một thương hiệu nhỏ và tái sử dụng kho hình/video giữa các bài, sau khi xác nhận bản Lite hỗ trợ các kênh bạn cần.","setup":"Bắt đầu từ tài liệu Mixpost Lite được dẫn trong README, không dùng bảng tính năng toàn bộ sản phẩm để suy đoán khả năng bản miễn phí.","limitations":"Nhiều tính năng được giới thiệu cho hệ sinh thái Mixpost có thể thuộc Pro/Enterprise. Tích hợp social phụ thuộc API nền tảng; tự host cần cấu hình và bảo trì.","github":{"stars":3656,"forks":549,"observedAt":"2026-09-03T16:07:36.757Z","url":"https://github.com/inovector/mixpost","pushedAt":"2026-03-16T10:06:38Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/inovector/mixpost/main/README.md","observedAt":"2026-09-03T16:09:18.107Z","sha256":"d4ac37ca5d57e6bd09624312c52a576f53304d41194a779edd8a14672ab067c4"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"inovector/mixpost:metadata","source_url":"https://github.com/inovector/mixpost","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Acharlie947%2Fsocial-media-skills%20repo%3Agitroomhq%2Fpostiz-app%20repo%3Ainovector%2Fmixpost%20repo%3Atrypostit%2Ftrypost%20repo%3Aleamsigc%2FMagicSync%20repo%3Amautic%2Fmautic%20repo%3Aknadh%2Flistmonk%20repo%3Auseplunk%2Fplunk&per_page=100","stars":3656,"forks":549,"license":"MIT"},"fetched_at":"2026-09-03T16:07:36.757Z"},{"source_type":"github","source_identifier":"inovector/mixpost:readme:d4ac37ca5d57e6bd09624312c52a576f53304d41194a779edd8a14672ab067c4","source_url":"https://raw.githubusercontent.com/inovector/mixpost/main/README.md","raw_metadata":{"sha256":"d4ac37ca5d57e6bd09624312c52a576f53304d41194a779edd8a14672ab067c4","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:18.107Z"}],"expected":null},{"identity":"repo:https://github.com/msitarzewski/agency-agents","slug":"agency-agents-92ac9094","name":"Agency Agents","type":"SKILL","status":"CANDIDATE","tagline":"Bạn có thể giao brief cho một nhóm vai trò AI, thay vì nhét mọi việc vào một prompt dài.","description":"Agency Agents là bộ hồ sơ chuyên gia AI với nhiệm vụ, quy trình và đầu ra riêng. Ngoài nhánh kỹ thuật, repo có Content Creator, TikTok Strategist, Instagram Curator, Reddit Community Builder và nhiều vai trò marketing. Giá trị với creator nằm ở việc chia việc rõ: ai tìm góc nội dung, ai viết, ai rà lại — không phải giả định AI đã thay được một agency thật.","long_description":"ĐIỂM NỔI BẬT\n• Vai trò chuyên biệt cho content đa nền tảng, lịch biên tập và kể chuyện thương hiệu.\n• Có nhánh TikTok, Instagram, LinkedIn, X và cộng đồng Reddit.\n• Có ứng dụng desktop cài chọn lọc agent vào các công cụ tương thích, không bắt buộc cài cả bộ.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nGiao cùng một brief sản phẩm cho Content Creator và TikTok Strategist, rồi so sánh bản bài viết với góc mở đầu video trước khi tự chọn.\n\nBẮT ĐẦU\nXem từng tệp vai trò hoặc dùng ứng dụng được README dẫn tới. Chỉ cài nhóm marketing/design cần dùng và kiểm tra quyền của agent nền.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nCác danh xưng chuyên gia và lời quảng bá trong README không chứng minh đầu ra luôn đúng hay đã được kiểm toán. Vẫn cần người duyệt nội dung, quyền đăng và dữ liệu cung cấp cho AI.","canonical_url":"https://github.com/msitarzewski/agency-agents","repository_url":"https://github.com/msitarzewski/agency-agents","documentation_url":"https://raw.githubusercontent.com/msitarzewski/agency-agents/main/README.md","owner_name":"msitarzewski","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":17,"categories":["content","social","design"],"primaryCategory":"content","selectionReason":"Phù hợp Content & Viết lách: Bạn có thể giao brief cho một nhóm vai trò AI, thay vì nhét mọi việc vào một prompt dài. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Bạn có thể giao brief cho một nhóm vai trò AI, thay vì nhét mọi việc vào một prompt dài.","highlights":["Vai trò chuyên biệt cho content đa nền tảng, lịch biên tập và kể chuyện thương hiệu.","Có nhánh TikTok, Instagram, LinkedIn, X và cộng đồng Reddit.","Có ứng dụng desktop cài chọn lọc agent vào các công cụ tương thích, không bắt buộc cài cả bộ."],"example":"Giao cùng một brief sản phẩm cho Content Creator và TikTok Strategist, rồi so sánh bản bài viết với góc mở đầu video trước khi tự chọn.","setup":"Xem từng tệp vai trò hoặc dùng ứng dụng được README dẫn tới. Chỉ cài nhóm marketing/design cần dùng và kiểm tra quyền của agent nền.","limitations":"Các danh xưng chuyên gia và lời quảng bá trong README không chứng minh đầu ra luôn đúng hay đã được kiểm toán. Vẫn cần người duyệt nội dung, quyền đăng và dữ liệu cung cấp cho AI.","github":{"stars":149869,"forks":24143,"observedAt":"2026-09-03T16:07:43.074Z","url":"https://github.com/msitarzewski/agency-agents","pushedAt":"2026-09-03T14:23:29Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/msitarzewski/agency-agents/main/README.md","observedAt":"2026-09-03T16:09:21.259Z","sha256":"a43c12d79595116d76c1540dc4a12dec68de7ca10de7e56016c242caf514104a"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"msitarzewski/agency-agents:metadata","source_url":"https://github.com/msitarzewski/agency-agents","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Aresend%2Freact-email%20repo%3Amjmlio%2Fmjml%20repo%3Acoreyhaines31%2Fmarketingskills%20repo%3Ablader%2Fhumanizer%20repo%3Adanielmiessler%2Ffabric%20repo%3Amsitarzewski%2Fagency-agents%20repo%3AOpenClaudia%2Fopenclaudia-skills%20repo%3Arealkimbarrett%2Fadvertising-skills&per_page=100","stars":149869,"forks":24143,"license":"MIT"},"fetched_at":"2026-09-03T16:07:43.074Z"},{"source_type":"github","source_identifier":"msitarzewski/agency-agents:readme:a43c12d79595116d76c1540dc4a12dec68de7ca10de7e56016c242caf514104a","source_url":"https://raw.githubusercontent.com/msitarzewski/agency-agents/main/README.md","raw_metadata":{"sha256":"a43c12d79595116d76c1540dc4a12dec68de7ca10de7e56016c242caf514104a","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:21.259Z"}],"expected":null},{"identity":"repo:https://github.com/appflowy-io/appflowy","slug":"appflowy-d0e43ac0","name":"AppFlowy","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Kho ý tưởng, brief và kiến thức của kênh cũng cần một nơi ở lâu dài.","description":"AppFlowy là workspace AI mã nguồn mở theo hướng thay thế Notion, nhấn mạnh kiểm soát dữ liệu và trải nghiệm ứng dụng đa nền tảng. Với người làm nội dung, đây là nơi có thể tổ chức phần chuẩn bị: tài liệu thương hiệu, ý tưởng và bản thảo. Nó bổ sung lớp quản lý kiến thức, chứ không phải công cụ tự dựng video hay đăng bài.","long_description":"ĐIỂM NỔI BẬT\n• Có ứng dụng desktop cho macOS, Windows và Linux cùng các bản di động.\n• Tác giả cung cấp hướng dẫn tự host để chủ động hơn với dữ liệu.\n• Dự án công khai giới hạn: không tuyên bố có đầy đủ mọi chức năng và thiết kế của Notion.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nTập hợp chân dung khán giả, ý tưởng series và ghi chú nghiên cứu của một kênh trong workspace, rồi dùng chúng làm đầu vào cho bước viết.\n\nBẮT ĐẦU\nTải ứng dụng từ liên kết phát hành chính chủ; xem riêng điều kiện đồng bộ, AI và self-host nếu cần.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nMã nguồn mở không đồng nghĩa mọi tính năng cloud/AI đều miễn phí hoặc dữ liệu luôn chỉ nằm trên máy. Kiểm tra cấu hình lưu trữ, đồng bộ và nhà cung cấp AI trước khi đưa tài liệu nhạy cảm vào.","canonical_url":"https://github.com/AppFlowy-IO/AppFlowy","repository_url":"https://github.com/AppFlowy-IO/AppFlowy","documentation_url":"https://raw.githubusercontent.com/AppFlowy-IO/AppFlowy/main/README.md","owner_name":"AppFlowy-IO","license":"AGPL-3.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":18,"categories":["content","research"],"primaryCategory":"content","selectionReason":"Phù hợp Content & Viết lách: Kho ý tưởng, brief và kiến thức của kênh cũng cần một nơi ở lâu dài. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Kho ý tưởng, brief và kiến thức của kênh cũng cần một nơi ở lâu dài.","highlights":["Có ứng dụng desktop cho macOS, Windows và Linux cùng các bản di động.","Tác giả cung cấp hướng dẫn tự host để chủ động hơn với dữ liệu.","Dự án công khai giới hạn: không tuyên bố có đầy đủ mọi chức năng và thiết kế của Notion."],"example":"Tập hợp chân dung khán giả, ý tưởng series và ghi chú nghiên cứu của một kênh trong workspace, rồi dùng chúng làm đầu vào cho bước viết.","setup":"Tải ứng dụng từ liên kết phát hành chính chủ; xem riêng điều kiện đồng bộ, AI và self-host nếu cần.","limitations":"Mã nguồn mở không đồng nghĩa mọi tính năng cloud/AI đều miễn phí hoặc dữ liệu luôn chỉ nằm trên máy. Kiểm tra cấu hình lưu trữ, đồng bộ và nhà cung cấp AI trước khi đưa tài liệu nhạy cảm vào.","github":{"stars":76235,"forks":5964,"observedAt":"2026-09-03T16:07:49.712Z","url":"https://github.com/AppFlowy-IO/AppFlowy","pushedAt":"2026-09-01T07:10:47Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/AppFlowy-IO/AppFlowy/main/README.md","observedAt":"2026-09-03T16:09:27.378Z","sha256":"f59d3e49037d392f36d7ea13d25485c5d54317f9aee7c61c4c2a47f067aa996d"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"AppFlowy-IO/AppFlowy:metadata","source_url":"https://github.com/AppFlowy-IO/AppFlowy","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Adeanpeters%2Fproduct-manager-skills%20repo%3Aphuryn%2Fpm-skills%20repo%3ATryGhost%2FGhost%20repo%3Aoutline%2Foutline%20repo%3Agetoutline%2Foutline%20repo%3AAFFiNE-io%2FAFFiNE%20repo%3AAppFlowy-IO%2FAppFlowy%20repo%3AKareadita%2FKavita&per_page=100","stars":76235,"forks":5964,"license":"AGPL-3.0"},"fetched_at":"2026-09-03T16:07:49.712Z"},{"source_type":"github","source_identifier":"AppFlowy-IO/AppFlowy:readme:f59d3e49037d392f36d7ea13d25485c5d54317f9aee7c61c4c2a47f067aa996d","source_url":"https://raw.githubusercontent.com/AppFlowy-IO/AppFlowy/main/README.md","raw_metadata":{"sha256":"f59d3e49037d392f36d7ea13d25485c5d54317f9aee7c61c4c2a47f067aa996d","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:27.378Z"}],"expected":null},{"identity":"repo:https://github.com/tryghost/ghost","slug":"ghost-9c989e0c","name":"Ghost","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Biến bài viết dài thành một kênh xuất bản riêng, thay vì chỉ gửi vào feed mạng xã hội.","description":"Ghost là nền tảng xuất bản của Ghost Foundation, phù hợp với website nội dung và newsletter. Repo cung cấp cách cài bằng Ghost CLI, tài liệu phát triển theme và API; người không muốn tự vận hành có thể chọn Ghost(Pro). Điểm phù hợp với creator là có một địa chỉ xuất bản thuộc hệ thống của mình để làm trung tâm cho nội dung.","long_description":"ĐIỂM NỔI BẬT\n• Có đường triển khai tự host và dịch vụ được quản lý riêng.\n• CLI hỗ trợ môi trường local để thử trước khi đưa lên máy chủ.\n• Hệ sinh thái tài liệu về theme và API giúp mở rộng trang nội dung theo thương hiệu.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nĐăng bài phân tích tool đầy đủ trên website, rồi dùng phiên bản rút gọn cho Facebook/LinkedIn và dẫn người muốn đọc sâu về bài gốc.\n\nBẮT ĐẦU\nThử local theo hướng dẫn hoặc dùng dịch vụ Ghost(Pro). Khi self-host, đối chiếu hosting stack được hỗ trợ và quy trình nâng cấp chính chủ.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nChi phí hosting, email và vận hành vẫn tồn tại. Ghost không tự tạo traffic; chất lượng bài viết, phân phối và quyền sử dụng tài nguyên vẫn do bạn chịu trách nhiệm.","canonical_url":"https://github.com/TryGhost/Ghost","repository_url":"https://github.com/TryGhost/Ghost","documentation_url":"https://raw.githubusercontent.com/TryGhost/Ghost/main/README.md","owner_name":"TryGhost","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":19,"categories":["content","social"],"primaryCategory":"content","selectionReason":"Phù hợp Content & Viết lách: Biến bài viết dài thành một kênh xuất bản riêng, thay vì chỉ gửi vào feed mạng xã hội. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Biến bài viết dài thành một kênh xuất bản riêng, thay vì chỉ gửi vào feed mạng xã hội.","highlights":["Có đường triển khai tự host và dịch vụ được quản lý riêng.","CLI hỗ trợ môi trường local để thử trước khi đưa lên máy chủ.","Hệ sinh thái tài liệu về theme và API giúp mở rộng trang nội dung theo thương hiệu."],"example":"Đăng bài phân tích tool đầy đủ trên website, rồi dùng phiên bản rút gọn cho Facebook/LinkedIn và dẫn người muốn đọc sâu về bài gốc.","setup":"Thử local theo hướng dẫn hoặc dùng dịch vụ Ghost(Pro). Khi self-host, đối chiếu hosting stack được hỗ trợ và quy trình nâng cấp chính chủ.","limitations":"Chi phí hosting, email và vận hành vẫn tồn tại. Ghost không tự tạo traffic; chất lượng bài viết, phân phối và quyền sử dụng tài nguyên vẫn do bạn chịu trách nhiệm.","github":{"stars":55144,"forks":11936,"observedAt":"2026-09-03T16:07:49.712Z","url":"https://github.com/TryGhost/Ghost","pushedAt":"2026-09-03T16:01:31Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/TryGhost/Ghost/main/README.md","observedAt":"2026-09-03T16:09:28.071Z","sha256":"8c8ab5173564bf5c397711bff1219d047790a560bac537332c07da12b345a411"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"TryGhost/Ghost:metadata","source_url":"https://github.com/TryGhost/Ghost","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Adeanpeters%2Fproduct-manager-skills%20repo%3Aphuryn%2Fpm-skills%20repo%3ATryGhost%2FGhost%20repo%3Aoutline%2Foutline%20repo%3Agetoutline%2Foutline%20repo%3AAFFiNE-io%2FAFFiNE%20repo%3AAppFlowy-IO%2FAppFlowy%20repo%3AKareadita%2FKavita&per_page=100","stars":55144,"forks":11936,"license":"MIT"},"fetched_at":"2026-09-03T16:07:49.712Z"},{"source_type":"github","source_identifier":"TryGhost/Ghost:readme:8c8ab5173564bf5c397711bff1219d047790a560bac537332c07da12b345a411","source_url":"https://raw.githubusercontent.com/TryGhost/Ghost/main/README.md","raw_metadata":{"sha256":"8c8ab5173564bf5c397711bff1219d047790a560bac537332c07da12b345a411","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:28.071Z"}],"expected":null},{"identity":"repo:https://github.com/danielmiessler/fabric","slug":"fabric-6fd6d07f","name":"Fabric","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Những prompt dùng tốt nên thành công cụ tái sử dụng, không nằm rải rác trong lịch sử chat.","description":"Fabric tổ chức prompt theo nhiệm vụ thực tế thành các pattern có thể chọn và dùng lại. Người không cần tự động hóa có thể tham khảo pattern; người quen dòng lệnh có thể gọi chúng qua Fabric với mô hình, bối cảnh và đầu vào riêng. Với creator, cách tiếp cận này giúp chuẩn hóa khâu đọc, rút ý và xử lý tài liệu trước khi viết.","long_description":"ĐIỂM NỔI BẬT\n• Chọn pattern và truyền bối cảnh thay vì viết lại yêu cầu từ đầu.\n• Hỗ trợ lựa chọn mô hình/nhà cung cấp và xuất kết quả ra tệp.\n• CLI có thao tác lấy transcript YouTube, kể cả lựa chọn timestamp, để đưa vào bước xử lý tiếp theo.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nDùng transcript của video bạn có quyền khai thác, rút các ý cần nghiên cứu rồi dựng brief cho bài viết mới và kiểm lại nguồn gốc.\n\nBẮT ĐẦU\nĐọc pattern trực tiếp hoặc cài bản Fabric theo README, cấu hình nhà cung cấp AI và chọn một nhiệm vụ nhỏ để thử trước.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nCLI cần làm quen; chi phí và quyền riêng tư phụ thuộc nhà cung cấp mô hình. Transcript có thể thiếu hoặc sai, và tóm tắt AI không thay thế xem lại nguồn.","canonical_url":"https://github.com/danielmiessler/Fabric","repository_url":"https://github.com/danielmiessler/Fabric","documentation_url":"https://raw.githubusercontent.com/danielmiessler/Fabric/main/README.md","owner_name":"danielmiessler","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":20,"categories":["content","research"],"primaryCategory":"content","selectionReason":"Phù hợp Content & Viết lách: Những prompt dùng tốt nên thành công cụ tái sử dụng, không nằm rải rác trong lịch sử chat. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Những prompt dùng tốt nên thành công cụ tái sử dụng, không nằm rải rác trong lịch sử chat.","highlights":["Chọn pattern và truyền bối cảnh thay vì viết lại yêu cầu từ đầu.","Hỗ trợ lựa chọn mô hình/nhà cung cấp và xuất kết quả ra tệp.","CLI có thao tác lấy transcript YouTube, kể cả lựa chọn timestamp, để đưa vào bước xử lý tiếp theo."],"example":"Dùng transcript của video bạn có quyền khai thác, rút các ý cần nghiên cứu rồi dựng brief cho bài viết mới và kiểm lại nguồn gốc.","setup":"Đọc pattern trực tiếp hoặc cài bản Fabric theo README, cấu hình nhà cung cấp AI và chọn một nhiệm vụ nhỏ để thử trước.","limitations":"CLI cần làm quen; chi phí và quyền riêng tư phụ thuộc nhà cung cấp mô hình. Transcript có thể thiếu hoặc sai, và tóm tắt AI không thay thế xem lại nguồn.","github":{"stars":43779,"forks":4251,"observedAt":"2026-09-03T16:07:43.074Z","url":"https://github.com/danielmiessler/Fabric","pushedAt":"2026-09-03T00:58:12Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/danielmiessler/Fabric/main/README.md","observedAt":"2026-09-03T16:09:22.417Z","sha256":"3e37d389f23db2926d7842065b361aeaa3873f954974226d32f22b9eb59270af"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"danielmiessler/Fabric:metadata","source_url":"https://github.com/danielmiessler/Fabric","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Aresend%2Freact-email%20repo%3Amjmlio%2Fmjml%20repo%3Acoreyhaines31%2Fmarketingskills%20repo%3Ablader%2Fhumanizer%20repo%3Adanielmiessler%2Ffabric%20repo%3Amsitarzewski%2Fagency-agents%20repo%3AOpenClaudia%2Fopenclaudia-skills%20repo%3Arealkimbarrett%2Fadvertising-skills&per_page=100","stars":43779,"forks":4251,"license":"MIT"},"fetched_at":"2026-09-03T16:07:43.074Z"},{"source_type":"github","source_identifier":"danielmiessler/Fabric:readme:3e37d389f23db2926d7842065b361aeaa3873f954974226d32f22b9eb59270af","source_url":"https://raw.githubusercontent.com/danielmiessler/Fabric/main/README.md","raw_metadata":{"sha256":"3e37d389f23db2926d7842065b361aeaa3873f954974226d32f22b9eb59270af","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:22.417Z"}],"expected":null}]'::jsonb) loop
  select * into existing from public.resources where external_identity=x->>'identity' for update;
  already:=found and existing.import_metadata->>'creatorImportHash'='70246f4c4a2f7774b985a83b1046397afb219b4521ac7e2ac8ae08790ad028cf';
  if already then continue; end if;
  if existing.id is not null and (existing.id::text is distinct from x->>'expected' or existing.editorial_revision<>0 or existing.status<>'CANDIDATE') then raise exception 'Candidate changed since snapshot: %',x->>'identity'; end if;
  if existing.id is null and x->>'expected' is not null then raise exception 'Candidate disappeared since snapshot'; end if;
  if existing.id is null then
    insert into public.resources(external_identity,slug,type,name,canonical_url) values(x->>'identity',x->>'slug',(x->>'type')::public.resource_type,x->>'name',x->>'canonical_url') returning id into rid;
  else rid:=existing.id; end if;
  update public.resources set name=x->>'name',type=(x->>'type')::public.resource_type,tagline=x->>'tagline',description=x->>'description',long_description=x->>'long_description',canonical_url=x->>'canonical_url',repository_url=x->>'repository_url',documentation_url=x->>'documentation_url',owner_name=x->>'owner_name',license=x->>'license',import_metadata=import_metadata||(x->'import_metadata')||jsonb_build_object('creatorImportHash','70246f4c4a2f7774b985a83b1046397afb219b4521ac7e2ac8ae08790ad028cf'),last_source_update_at=(x#>>'{import_metadata,creatorCatalog,github,observedAt}')::timestamptz,editorial_revision=editorial_revision+1,updated_at=now() where id=rid;
  for s in select value from jsonb_array_elements(x->'sources') loop
    insert into public.resource_sources(resource_id,source_type,source_identifier,source_url,raw_metadata,fetched_at) values(rid,s->>'source_type',s->>'source_identifier',s->>'source_url',s->'raw_metadata',(s->>'fetched_at')::timestamptz) on conflict(resource_id,source_type,source_identifier) do update set source_url=excluded.source_url,raw_metadata=excluded.raw_metadata,fetched_at=excluded.fetched_at;
  end loop;
  insert into public.resource_metric_snapshots(resource_id,source_type,metric_key,metric_value,captured_at) values(rid,'github','stars',(x#>>'{import_metadata,creatorCatalog,github,stars}')::numeric,(x#>>'{import_metadata,creatorCatalog,github,observedAt}')::timestamptz),(rid,'github','forks',(x#>>'{import_metadata,creatorCatalog,github,forks}')::numeric,(x#>>'{import_metadata,creatorCatalog,github,observedAt}')::timestamptz) on conflict do nothing;
  insert into public.resource_evidence_jobs(resource_id) values(rid) on conflict do nothing;
end loop;
end $creator_import$;
commit;
